     ) as spu_vsku_property

    ,grass_date
    ,CAST(timestamp_timezone_convert(log_timestamp, grass_region, 'yyyy-MM-dd') AS DATE) AS local_date
    ,CAST(timestamp_timezone_convert(log_timestamp, grass_region, "HH") AS INT) AS local_hour
    ,CAST(timestamp_timezone_convert(log_timestamp, "SG", "yyyy-MM-dd") AS DATE) AS regional_date
    ,CAST(timestamp_timezone_convert(log_timestamp, "SG", "HH") AS INT) AS regional_hour
    ,grass_region
    ,case
        when event_type = 'impression' then 'omni_impression'
        when event_type = 'click' then 'omni_click'
    end as operation
FROM
    traffic_omni_oa.dwd_item_event_log_di__reg_sensitive_live
where grass_date = ${local_date} and grass_region in (${grass_region})

