-- deprecated: False
-- sha256: e22100dd1c20886590eaac90098383b15ca410028e63a7fdae04dbc3028bd912
CREATE TEMPORARY VIEW omni_order_parse_${grass_region_without_quote} AS
SELECT
    platform
    ,split(feature_detail_omni, '-')[0] AS page_type
    ,if(split(feature_detail_omni,'-')[2] IS NOT NULL, array(split(feature_detail_omni,'-')[1]), NULL) AS page_section
    ,if(split(feature_detail_omni,'-')[2] IS NOT NULL, split(feature_detail_omni,'-')[2], split(feature_detail_omni,'-')[1]) AS target_type
    ,source1_page_type
    ,if(source1_page_section IS NULL, NULL, array(source1_page_section)) AS source1_page_section
    ,source1_target_type
    ,source1_location_property.location as source1_location
    ,source2_page_type
    ,if(source2_page_section IS NULL, NULL, array(source2_page_section)) AS source2_page_section
    ,source2_target_type
    ,source2_location_property.location as source2_location
    ,concat_ws(
        '-',
        array(
            source1_mapped_page_type,
            source1_page_section,
            source1_target_type
        )
    ) AS source1_feature_detail
    ,concat_ws(
        '-',
        array(
            source2_mapped_page_type,
            source2_page_section,
            source2_target_type
        )
    ) AS source2_feature_detail
    ,feature_detail_omni AS feature_detail
    ,app_version
    ,rn_version
    ,CAST(click_common_property.is_ads AS Boolean) AS is_ads
    ,click_location_property.location AS location
    ,order_item_id AS item_id
    ,click_recommendation_property.collection_id AS knode_id
    ,click_search_property.keyword AS keyword
    ,shop_id
    ,device_id
    ,user_id
    ,array_distinct(
        flatten(
            array(
                coalesce(from_json(click_search_property.ab_sign, 'ARRAY<INT>'), array()),
                coalesce(transform(
                        split(regexp_extract(click_recommendation_property.recommendation_info,'AB:([^,]*)', 1), "\\|"),
                        x -> CAST(if(split(x, '_')[2] IS NOT NULL, split(x, '_')[2], x) AS INT)
                    ), array()
                ),
                coalesce(from_json(source1_search_property.ab_sign, 'ARRAY<INT>'), array()),
                coalesce(transform(
                        split(regexp_extract(source1_recommendation_property.recommendation_info,'AB:([^,]*)', 1), "\\|"),
                        x -> CAST(if(split(x, '_')[2] IS NOT NULL, split(x, '_')[2], x) AS INT)
                    ), array()
                ),
                coalesce(from_json(source2_search_property.ab_sign, 'ARRAY<INT>'), array()),
                coalesce(transform(
                        split(regexp_extract(source2_recommendation_property.recommendation_info,'AB:([^,]*)', 1), "\\|"),
                        x -> CAST(if(split(x, '_')[2] IS NOT NULL, split(x, '_')[2], x) AS INT)
                    ), array()
                ),
                coalesce(exp_group, array()),
                coalesce(source1_exp_group, array()),
                coalesce(source2_exp_group, array()),
                coalesce(click_common_property.be_ab, array()),
                coalesce(source1_common_property.be_ab, array()),
                coalesce(source2_common_property.be_ab, array())
            )
        )
    ) AS exp_group_ids
    ,order_fraction * atc_prorate * first_touchpoint_item AS operation_cnt
    ,click_common_property.card_type AS card_type
    ,order_place_timestamp*1000 AS event_timestamp
    ,NULL AS log_timestamp
    ,NULL AS event_id
    ,NULL AS is_group_buy
    ,CASE
        WHEN
            click_ctx_itemid > 0
            AND click_ctx_shopid > 0
            THEN array(
                named_struct(
                    'shopid',
                    cast(click_ctx_shopid AS BIGINT),
                    'itemid',
                    cast(click_ctx_itemid AS BIGINT)
                ))
        ELSE NULL
    END AS ctx_items
    ,order_model_id AS model_id
    ,gmv * atc_prorate * first_touchpoint_item AS gmv
    ,gmv_usd * atc_prorate * first_touchpoint_item AS gmv_usd
    ,place_sellergmv * atc_prorate * last_touchpoint_item as seller_gmv
    ,place_sellergmv_usd * atc_prorate * last_touchpoint_item as seller_gmv_usd
    ,NULL AS is_back
    ,coalesce(
        regexp_extract(click_recommendation_property.recommendation_info, 'REQID:([^,]*)', 1),
        click_search_property.request_id,
        click_video_property.request_id
    ) AS request_id
    ,get_json_object(click_search_property.scenario, '$.key') AS search_scenario_key
    ,click_search_property.search_entrance
    ,click_search_property.search_mid
    ,click_search_property.image_md5 AS md5
    ,click_search_property.item_similarity
    ,click_search_property.image_source
    ,NULL AS liked
    ,click_search_property.sort_by AS sort_type
    ,order_id
    ,CASE
         WHEN size(click_search_property.rule_ids) >= 1 THEN
             concat_ws(",", click_search_property.rule_ids)
         ELSE
             coalesce(
                 regexp_replace(
                     regexp_extract(
                         click_recommendation_property.recommendation_info,
                         'QUES:([^,]*)',
                         1
                     ),
                     "\\|",
                     ","
                 ),
                 ''
             )
     END AS queues
    ,platform_implementation
    ,click_event_timestamp AS oa_click_event_timestamp
    ,atc_event_timestamp AS oa_atc_event_timestamp
    ,window_day
