    ,TRANSFORM(click_search_property.search_filter, x -> struct(x.filter_group_name, x.filter_name, x.filter_option, x.is_shortcut_filter)) AS search_filter
    ,source1_mapped_page_type
    ,source2_mapped_page_type
    ,source1_search_property.sort_by as source1_sort_by
    ,source2_search_property.sort_by as source2_sort_by
    ,coalesce(
