    ,source2_search_property.global_session_id AS source2_global_session_id
    ,source1_search_property.search_session_id AS source1_search_session_id
    ,source2_search_property.search_session_id AS source2_search_session_id
    ,source1_search_property.search_mid AS source1_search_mid
    ,source2_search_property.search_mid AS source2_search_mid
    ,click_video_property.content_type as content_type
    ,source1_video_property.content_type as source1_content_type
    ,source2_video_property.content_type as source2_content_type
    ,feature_omni
    ,source1_feature_omni
    ,source2_feature_omni
    ,feature_group_omni
    ,source1_feature_group_omni
    ,source2_feature_group_omni
    ,CAST(click_common_property.ads_id AS BIGINT) AS ads_id
    ,CAST(source1_common_property.ads_id as BIGINT)  as source1_ads_id
    ,CAST(source2_common_property.ads_id as BIGINT)  as source2_ads_id
    ,business_line as reporting_business_line
