                last_keyword: STRING,
                order: STRING,
                voice_search_session_id: STRING
            >,
            rating_score STRING,
            query_rewrite STRUCT<
                rewrite_keyword: STRING,
                fe_query_rewrite_status: INT,
                ori_keyword: STRING,
                rewrite_type: INT
            >,
            layout_type: INT,
            edd: STRING,
            title_info STRUCT<title_text:STRING,title_is_rewrite:BOOLEAN>,
            label_icon_info STRUCT<
                labels: ARRAY<STRUCT<label_text:STRING,label_type:STRING,label_location:INT>>,
                seller_flags: ARRAY<STRING>
            >,
            module STRUCT<
                location: INT,
                title: STRING,
                impressed_keyword: STRING,
                clicked_keyword: STRING
            >,
            keyword_source: INT,
            status_code_info: ARRAY<STRING>,
            prefill_id: BIGINT,
            use_mobile_vad: BOOLEAN,
            edt_info STRING,
            manual_stop_info STRUCT<
                is_manual_stop: STRING
            >,
            box_xy STRING,
            box STRUCT<
                box_xy: STRING
            >,
            classification: STRING,
            traffic_info STRUCT<
                biz_flag: ARRAY<STRING>,
                tc_rule_array: ARRAY<STRING>
            >
        >,
        search_params STRUCT<
            keyword: STRING,
            searchPrefill: INT,
            order: STRING,
            reserved_keyword: STRING
        >,
        fe_performance_info STRUCT<
            isCache: BOOLEAN
        >,
        fe_performance STRUCT<
            total_duration: BIGINT,
            stages_duration: ARRAY<STRING>
        >,
        be_performance STRUCT<
            server_cost: BIGINT,
            request_pack_size: BIGINT,
            response_pack_size: BIGINT
        >,
        item STRUCT<
            itemid: STRING,
            shopid: STRING,
            recommendation_info: STRING,
            display_price: STRING,
            rating: STRING,
            display_price_model_id: BIGINT
        >,
        param STRUCT<
            recommendation_algorithm: STRING
        >,
        be_ab ARRAY<INT>,
        params STRUCT<
            recommendation_algorithm: STRING,
            content_mix_frame_tab_name: STRING,
            item_id: STRING,
            is_ads: STRING,
            shop_id: STRING,
            index: STRING,
            content_type: STRING,
            sv_source_page: STRING,
            sv_source_request_id: STRING,
            sv_source_location: STRING,
            sv_source_search_session_id: STRING,
            sv_source_item_id: STRING,
            seg_duration: STRING,
            sv_source_search_info: STRING,
            sv_source_recommendation_algorithm: STRING
        >,
        position STRUCT<
            current_page: STRING
        >,
        `vsku_info` STRING,
        `ctx_item_type` STRING,
        `edt_label` STRUCT<
            label_content: STRING
        >,
        `meta` STRUCT<
            business_id: STRING
        >,
        `first_label_id` BIGINT,
        `first_label` STRING,
        `first_label_content` STRING,
        `second_label_id` BIGINT,
        `second_label` STRING,
        `second_label_content` STRING,
        `highlight_video_playback_loop` INT,
        `ai_search_info` STRING,
        `srp_ai_topic_info` STRUCT <
            srp_location: INT,
            srp_title: STRING
        >,
        `topic_info` STRUCT <
            topic_title: STRING,
            topic_location: INT
        >,
        `aiminifeed_title` STRING,
        `llm_rewrite_keyword` STRING,
        `shop` STRUCT<
            item_list ARRAY<BIGINT>
        >,
        `video_play_loop` DOUBLE,
        `video_info` ARRAY<STRUCT<video_play_loop: DOUBLE>>,
         match_id STRING,
         `title_info` STRUCT <
            title_id STRING,
            title_text STRING,
            title_is_rewrite BOOLEAN
        >,
        `card_unique_id` STRING,
        `image_hashcode` STRING,
        `price_after_voucher` STRING
        ') AS parse_data
        ,srdi_fastjson2_from_json(
            get_json_object(data, '$.search_info'),
            '
                `is_ads` STRING,
                `ab_sign` ARRAY<INT>,
                `request_id` STRING,
                `recall_score_list` ARRAY<STRUCT<recall_level: INT, score: DOUBLE>>,
                `ruleids` STRING,
                `item_similarity` STRING,
                `user_type` ARRAY<INT>,
                `groupid` INT,
                `reqid` STRING,
                `attr_data_type` STRING,
                `item_type` INT,
                `query_rewrite` STRUCT<
                    rewrite_keyword: STRING,
                    fe_query_rewrite_status: INT,
                    ori_keyword: STRING,
                    rewrite_type: INT
                >,
                `image_id` STRING,
                `long_image_id` STRING
            '
        ) AS parse_search_info
        ,srdi_fastjson2_from_json(
            data,'
                `search_FE` STRUCT <
                    search_filter: ARRAY<
                        STRUCT<
                            filter_group_name:STRING,
                            filter_name:STRING,
                            filter_option:STRING,
                            is_shortcut:BOOLEAN,
                            address_id:BIGINT
                        >
                    >
                >
            '
        ) AS parse_search_filter
FROM
traffic.shopee_traffic_dwd_click_hi__reg_s1_live;

--sql_divide_splitter--

CREATE TEMPORARY VIEW traffic_click_parse_${grass_region_without_quote} AS
SELECT
    platform
    ,page_type
    ,if(operation='stay_impression', array(page_section1), page_section) as page_section    -- for stay_impression, page_section is null, use page_section1 instead
    ,target_type
    ,NULL AS source1_page_type
    ,NULL AS source1_page_section
    ,NULL AS source1_target_type
    ,NULL AS source2_page_type
    ,NULL AS source2_page_section
    ,NULL AS source2_target_type
    ,NULL AS source1_feature_detail
    ,NULL AS source2_feature_detail
    ,concat_ws(
        '-',
        array(
            page_type,
            page_section[0],
            target_type
        )
    ) AS feature_detail
    ,app_version
    ,rn_version
    ,cast(
        coalesce(
            parse_data.is_ads,
            parse_search_info.is_ads,
            parse_data.params.is_ads
        ) AS BOOLEAN
    ) AS is_ads
    ,cast(
        coalesce(
            parse_data.location,
            parse_data.search_FE.item.location,
            parse_data.search_FE.location,
            parse_data.search_FE.absolute_location,
            parse_data.params.index,
            parse_data.search_FE.module.location
        ) AS INT
    ) AS location
    ,cast(
        coalesce(
            parse_data.itemid,
            parse_data.item.itemid,
            parse_data.item_id,
            parse_data.params.item_id
        ) AS BIGINT
    ) AS item_id
    ,cast(parse_data.collection_id AS STRING) AS knode_id
    ,cast(coalesce(
        parse_data.search_FE.search_params.keyword,
        parse_data.search_params.keyword,
        parse_data.keyword,
        parse_data.search_FE.keyword,
        parse_data.search_FE.hint_text,
        parse_data.hint_text
    ) AS STRING) AS keyword
    ,cast(coalesce(
        parse_data.shopid,
        parse_data.item.shopid,
        parse_data.shop_id,
        parse_data.search_FE.shopid,
        parse_data.params.shop_id
    ) AS BIGINT) AS shop_id
    ,deviceid AS device_id
    ,userid AS user_id
    ,array_distinct(
        flatten(
            array(
                coalesce(parse_search_info.ab_sign, array()),
                coalesce(transform(
                    split(regexp_extract(parse_data.recommendation_info,'AB:([^,]*)', 1), "\\|"),
                    x -> CAST(if(split(x, '_')[2] IS NOT NULL, split(x, '_')[2], x) AS INT)
                    ), array()
                ),
                coalesce(transform(
                    split(regexp_extract(parse_data.params.recommendation_algorithm,'AB:([^,]*)', 1), "\\|"),
                    x -> CAST(if(split(x, '_')[2] IS NOT NULL, split(x, '_')[2], x) AS INT)
                    ), array()
                ),
                coalesce(parse_data.be_ab, array()),
                coalesce(exp_group_id, array()),
                coalesce(transform(
                    split(regexp_extract(url_decode(regexp_extract(parse_data.params.recommendation_algorithm, 'MIXERINFO:([^,]+)', 1))
                    ,'AB:([^,]*)', 1), "\\|"),
                    x -> CAST(if(split(x, '_')[2] IS NOT NULL, split(x, '_')[2], x) AS INT)
                    ), array())
            )
        )
    ) AS exp_group_ids
    ,1 AS operation_cnt
    ,cast(parse_data.card_type AS STRING) AS card_type
    ,event_timestamp
    ,log_timestamp
    ,event_id
    ,cast(parse_data.is_group_buy AS BOOLEAN) AS is_group_buy
    ,CASE
        WHEN
            cast(
                parse_data.ctx_itemid AS BIGINT
            ) IS NOT NULL
            AND cast(
                parse_data.ctx_shopid AS BIGINT
            ) IS NOT NULL
            THEN array(
                named_struct(
                    'shopid',
                    cast(
                        parse_data.ctx_shopid AS BIGINT
                    ),
                    'itemid',
                    cast(
                        parse_data.ctx_itemid AS BIGINT
                    )
                ))
        ELSE NULL
    END AS ctx_items
    ,cast(parse_data.model_id AS BIGINT) AS model_id
    ,NULL AS place_order_gmv
    ,NULL AS place_order_gmv_local
    ,is_back
    ,get_json_object(data, '$.search_FE.search_entrance.entrance') AS search_entrance
    ,get_json_object(data, '$.search_FE.search_entrance.mid') AS search_mid
    ,coalesce(
        NULLIF(parse_search_info.request_id, '')
        ,NULLIF(regexp_extract(parse_data.recommendation_info,'REQID:([^,]*)', 1), '')
        ,NULLIF(regexp_extract(parse_data.params.recommendation_algorithm,'REQID:([^,]*)', 1), '')
        ,NULLIF(GET_JSON_OBJECT(GET_JSON_OBJECT(data, '$.params.search_info'), '$.request_id'), '')
        ,NULLIF(GET_JSON_OBJECT(GET_JSON_OBJECT(data, '$.params.search_info'), '$.reqid'), '')
    ) AS request_id
    ,parse_data.search_FE.search_params.search_scenario.key AS search_scenario_key
    ,CASE
            WHEN page_type = 'pre_search' AND page_section[0] = 'search_bar' AND target_type = 'search_prefill' THEN parse_data.search_FE.prefill_type
            WHEN page_type = 'pre_search' AND page_section[0] = 'search_bar' AND target_type = 'hint_keyword' THEN parse_data.search_FE.input_type
            WHEN page_type = 'search_suggest_page' AND page_section[0] = 'search_bar' AND target_type = 'hint_keyword' THEN parse_data.search_FE.input_type
            WHEN page_type = 'home' AND page_section IS NULL AND target_type = 'search_bar' THEN parse_data.prefill_type
    END AS search_mid_value
    ,parse_data.search_FE.md5 AS md5
    ,cast(parse_search_info.item_similarity AS DOUBLE) AS item_similarity
    ,CASE
        WHEN parse_data.search_FE.image_source = '' THEN NULL
        ELSE parse_data.search_FE.image_source
    END AS image_source
    ,cast(parse_data.liked AS BOOLEAN) AS liked
    ,parse_data.search_FE.search_params.sortBy AS sort_type
    ,pre_source
    ,CASE
        WHEN target_type = 'item' THEN target_property
        ELSE null
    END AS target_property
    ,CASE
         WHEN page_type = 'home'AND page_section[0]='shopee_video' AND target_type = 'video_card' THEN regexp_extract(parse_data.param.recommendation_algorithm, 'REQID:([^,]*)', 1)
         WHEN page_type = 'home'AND page_section[0]='daily_discover' AND target_type = 'video' THEN regexp_extract(parse_data.param.recommendation_algorithm, 'REQID:([^,]*)', 1)
         ELSE null
    END AS video_request_id
    ,CASE
         WHEN page_type = 'home'AND page_section[0]='shopee_video' AND target_type = 'video_card' THEN decode_video_id(parse_data.video_id)
         WHEN page_type = 'home'AND page_section[0]='daily_discover' AND target_type = 'video' THEN decode_video_id(parse_data.video_id)
         ELSE null
    END AS video_id
    ,CASE
         WHEN page_type = 'search' AND page_section[0] is null AND target_type = 'video' THEN decode_video_id(parse_data.video_id)
         WHEN page_type = 'search' AND page_section[0] is null AND target_type = 'livestream' THEN parse_data.streaming_id
         WHEN page_type = 'home' AND page_section[0]='daily_discover' AND target_type = 'livestream' THEN parse_data.streaming_id
         WHEN page_type = 'home' AND page_section[0]='shopee_video' AND target_type = 'video_card' THEN decode_video_id(parse_data.video_id)
         WHEN page_type = 'home' AND page_section[0]='daily_discover' AND target_type = 'video' THEN decode_video_id(parse_data.video_id)
         WHEN page_type = 'product' AND page_section[0]='you_may_also_like' AND target_type = 'video' THEN decode_video_id(parse_data.video_id)
         ELSE NULL
    END AS content_id
    ,CASE
        WHEN operation in ('stay_view','stay_impression') THEN BIGINT(get_json_object(target_property, "$.duration"))
        WHEN operation in ('action_section_duration') THEN BIGINT(get_json_object(data, "$.duration"))
        ELSE NULL
    END AS page_stay_duration
    ,CASE
          WHEN parse_search_info.ruleids IS NOT NULL THEN
              regexp_replace(
                  parse_search_info.ruleids,
                  '\\[|\\]',
                  ''
              )
          ELSE
              COALESCE(
                  regexp_replace(
                      regexp_extract(
                          COALESCE(
                              parse_data.recommendation_info,
                              parse_data.item.recommendation_info
                          ),
                          'QUES:([^,]*)',
                          1
                      ),
                      "\\|",
                      ","
                  ),
                  ''
              )
     END AS queues
    ,session_id
    ,COALESCE(parse_data.search_FE.search_params.search_session_id, parse_data.params.sv_source_search_session_id) AS search_session_id
    ,parse_data.search_FE.search_params.global_session_id as global_session_id
    ,parse_data.search_FE.input_type AS input_type
    ,parse_data.search_FE.prefill_type AS prefill_type
    ,cast(parse_data.search_FE.rating_score as DOUBLE) as rating_score
    ,platform_implementation
    ,parse_data.search_FE.version as camera_page_version
    ,parse_data.upstream AS upstream_feature
    ,TRANSFORM(parse_search_filter.search_FE.search_filter, x -> STRUCT(x.filter_group_name, x.filter_name, x.filter_option, x.is_shortcut)) AS search_filter
    ,last_view_event_id
    ,last_view_civ_id
    ,civ_id
    ,operation as original_operation
    ,parse_search_info.groupid as groupid
    ,parse_search_info.user_type as user_type
    ,parse_search_info.reqid as search_guide_request_id
    ,parse_data.search_FE.search_params.last_keyword as last_keyword
    ,parse_data.search_params.searchPrefill AS search_prefill_id
    ,COALESCE(parse_data.search_FE.search_params.order, parse_data.search_params.order) AS sort_order
    ,parse_data.user_input AS user_input
    ,COALESCE(parse_data.search_FE.query_rewrite.rewrite_keyword, parse_search_info.query_rewrite.rewrite_keyword) AS rewrite_keyword
    ,COALESCE(parse_data.search_FE.query_rewrite.ori_keyword, parse_search_info.query_rewrite.ori_keyword) AS origin_rewrite_keyword
    ,COALESCE(parse_data.search_FE.query_rewrite.fe_query_rewrite_status, parse_search_info.query_rewrite.fe_query_rewrite_status) AS fe_querywrite_status
    ,COALESCE(parse_data.search_FE.query_rewrite.rewrite_type, parse_search_info.query_rewrite.rewrite_type) AS rewrite_id
    ,parse_data.search_params.reserved_keyword AS reserved_keyword
    ,parse_data.display_ad_tag AS display_ad_tag
    ,parse_data.ads_id AS ads_id
    ,parse_search_info.attr_data_type AS attr_data_type
    ,data
    ,parse_data.traffic_source AS traffic_source
    ,COALESCE(parse_data.search_FE.item.edt, parse_data.edt_label.label_content) AS edt_string_type
    ,parse_data.search_FE.item.show_labels AS show_labels
    ,COALESCE(parse_data.params.content_mix_frame_tab_name, parse_data.content_mix_frame_tab_name) AS content_mix_frame_tab_name
    ,parse_data.position.current_page AS position_current_page
    ,CASE
        WHEN parse_data.search_FE.image_aspect_ratio = '3:4' THEN parse_search_info.long_image_id
        ELSE coalesce(parse_search_info.image_id, parse_data.image_hashcode)
    END AS image_id
    ,get_json_object(get_json_object(get_json_object(data,'$.search_info'), '$.search_xui_info'),'$.xui_item_status') AS xui_item_status
    ,get_json_object(data,'$.search_info.search_xui_info.xui_image_stage') AS xui_image_stage
    ,cast(parse_data.ctx_item_type as int) as ctx_item_type
    ,parse_data.vsku_info as vsku_info
    ,get_json_object(data, '$.search_FE.module.clicked_keyword.keyword_type') AS module_keyword_type
    ,get_json_object(data, '$.search_FE.search_entrance.context.keyword_type') AS entrance_keyword_type
    ,parse_data.shop_recall_type AS shop_recall_type
    ,parse_data.search_FE.image_aspect_ratio AS image_aspect_ratio
    ,parse_data.search_FE.dre_version AS dre_version
    ,parse_data.search_FE.layout_variant AS layout_variant
    ,parse_data.fe_performance_info.isCache AS is_cache
    ,parse_data.fe_performance.total_duration AS total_duration
    ,parse_data.be_performance.server_cost AS server_cost
    ,parse_data.be_performance.request_pack_size AS request_pack_size
    ,parse_data.be_performance.response_pack_size AS response_pack_size
    ,parse_data.fe_performance.stages_duration AS stages_duration
    ,parse_data.first_label_id AS first_label_id
    ,parse_data.first_label AS first_label
    ,parse_data.first_label_content AS first_label_content
    ,parse_data.second_label_id AS second_label_id
    ,parse_data.second_label AS second_label
    ,parse_data.second_label_content AS second_label_content
    ,parse_data.search_FE.layout_type AS layout_type
    ,TRANSFORM(parse_search_filter.search_FE.search_filter, x -> x.address_id) AS search_filter_address_id
    ,parse_data.search_FE.edd AS edd
    ,coalesce(parse_data.item.display_price,parse_data.price_after_voucher) AS display_price
    ,parse_data.item.rating AS rating
    ,parse_data.search_FE.title_info AS title_info
    ,parse_data.search_FE.label_icon_info.labels AS labels
    ,parse_data.search_FE.label_icon_info.seller_flags AS seller_flags
    ,parse_data.search_FE.item.sold_cnt_str AS sold_cnt_str
    ,parse_data.search_FE.item.shipped_from AS shipped_from
    ,parse_data.highlight_video_playback_loop as highlight_video_playback_loop
    ,parse_data.params.content_type AS content_type
    ,parse_data.params.sv_source_page AS sv_source_page
    ,parse_data.meta.business_id AS business_id
    ,GET_JSON_OBJECT(GET_JSON_OBJECT(GET_JSON_OBJECT(data,'$.search_info'), '$.search_xui_info'), '$.library_name') AS library_name
    ,CAST(FROM_JSON(GET_JSON_OBJECT(GET_JSON_OBJECT(GET_JSON_OBJECT(data,'$.search_info'), '$.search_xui_info'), '$.label_source'), 'ARRAY<STRING>') AS ARRAY<STRING>) AS label_source
    ,GET_JSON_OBJECT(GET_JSON_OBJECT(GET_JSON_OBJECT(data,'$.search_info'), '$.search_xui_info'), '$.title_source') AS title_source
    ,COALESCE(
        parse_data.search_FE.search_params.voice_search_session_id
        ,GET_JSON_OBJECT(data, '$.search_FE.search_entrance.context.voice_search_session_id')
    ) AS voice_search_session_id
    ,CAST(GET_JSON_OBJECT(data, '$.llm_dt_recall') AS BOOLEAN) AS is_llm_deepthinking
    ,COALESCE(
        CAST(GET_JSON_OBJECT(data, '$.is_llm_card') AS BOOLEAN)
        ,CAST(GET_JSON_OBJECT(data, '$.search_FE.search_entrance.context.rs_is_llm_card') AS BOOLEAN)
    ) AS rs_is_llm_card
    ,FROM_JSON(GET_JSON_OBJECT(data, '$.search_FE.search_filter'), 'ARRAY<STRING>') AS search_filter_string
    ,parse_data.search_FE.keyword_source AS hint_keyword_source
    ,parse_data.search_FE.module.impressed_keyword AS rs_impressed_keyword
    ,parse_data.search_FE.module.clicked_keyword AS rs_clicked_keyword
    ,COALESCE(
          NULLIF(parse_data.params.sv_source_request_id, '')
         ,NULLIF(regexp_extract(parse_data.params.sv_source_recommendation_algorithm,'REQID:([^,]*)', 1), '')
         ,NULLIF(GET_JSON_OBJECT(parse_data.params.sv_source_search_info, '$.request_id'), '')
     ) AS sv_source_request_id
    ,cast(parse_data.params.sv_source_location as int) AS sv_source_location
    ,parse_data.aiminifeed_title AS ai_minifeed_card_title
    ,parse_data.llm_rewrite_keyword AS llm_rewrite_keyword
    ,parse_data.topic_info.topic_title AS topic_title
    ,parse_data.topic_info.topic_location AS topic_location
    ,parse_data.srp_ai_topic_info.srp_location AS ai_topic_srp_location
    ,parse_data.srp_ai_topic_info.srp_title AS ai_topic_srp_title
    ,parse_data.search_FE.module.title AS fe_module_title
    ,parse_data.shop.item_list AS shop_layout_item_list
    ,COALESCE(parse_data.url, parse_data.search_FE.url) AS url
    ,parse_search_info.item_type AS item_type
    ,parse_data.search_FE.status_code_info AS fe_status_code_info
    ,cast(parse_data.params.sv_source_item_id as bigint) AS sv_source_item_id
    ,parse_data.params.seg_duration AS seg_duration
    ,cast(parse_data.content_location as int) as content_location
    ,parse_data.live_scene_parameters.live_in_search.request_id as live_in_search_request_id
    ,cast(parse_data.live_scene_parameters.live_in_search.itemid as bigint) as live_in_search_item_id
    ,cast(parse_data.live_scene_parameters.live_in_search.location as int) as live_in_search_location
    ,parse_data.ctx_streaming_id as ctx_streaming_id
    ,parse_data.ctx_from_source as ctx_from_source
    ,parse_data.search_FE.prefill_id AS prefill_id_from_csa
    ,COALESCE(parse_data.video_info[0].video_play_loop,parse_data.video_play_loop) AS video_play_loop
    ,parse_data.match_id AS match_id
    ,parse_data.title_info.title_id AS title_id
    ,COALESCE(parse_data.title_info.title_text, parse_data.search_FE.title_info.title_text) AS title_text
    ,COALESCE(parse_data.title_info.title_is_rewrite, parse_data.search_FE.title_info.title_is_rewrite) AS title_is_rewrite
    ,parse_data.search_FE.use_mobile_vad AS use_mobile_vad
    ,parse_data.ai_search_info AS ai_search_info
    ,COALESCE(parse_data.search_FE.item.item_unique_key, parse_data.card_unique_id) AS item_unique_key
    ,CAST(GET_JSON_OBJECT(parse_data.search_FE.edt_info, '$.edt_model_id') AS BIGINT) AS edt_model_id
    ,GET_JSON_OBJECT(parse_data.search_FE.edt_info, '$.edt_tracking_info.a') AS edt_pre_selected_shipping_id
    ,GET_JSON_OBJECT(parse_data.search_FE.edt_info, '$.edt_tracking_info.b') AS pre_selected_edt
    ,GET_JSON_OBJECT(parse_data.search_FE.edt_info, '$.edt_tracking_info.c') AS display_type_edt
    ,GET_JSON_OBJECT(parse_data.search_FE.edt_info, '$.edt_tracking_info.d') AS edt_buyer_address
    ,parse_data.search_FE.search_entrance.last_entrance AS last_entrance
    ,parse_data.search_FE.error_type AS search_fe_error_type
    ,parse_data.search_FE.manual_stop_info.is_manual_stop AS is_manual_stop
    ,CASE
        WHEN parse_data.search_FE.box.box_xy IS NOT NULL THEN parse_data.search_FE.box.box_xy
        ELSE parse_data.search_FE.box_xy
    END AS search_box_xy
    ,parse_data.search_FE.classification AS fe_voice_search_classification
    ,parse_data.search_FE.traffic_info.biz_flag AS biz_flag
    ,parse_data.search_FE.traffic_info.tc_rule_array AS tc_rule_array
    ,parse_data.search_FE.search_params.search_scenario.be_key AS search_scenario_be_key
    ,parse_data.item.display_price_model_id AS display_price_model_id

    ,local_date
    ,local_hour
    ,regional_date
    ,regional_hour
    ,grass_region
    ,operation
FROM
    traffic_click_pre_parse_${grass_region_without_quote};

