CREATE TEMPORARY VIEW traffic_view_parse_${grass_region_without_quote} AS
SELECT
    platform
    ,page_type
    ,page_section
    ,target_type
    ,NULL AS source1_page_type
    ,NULL AS source1_page_section
    ,NULL AS source1_target_type
    ,NULL AS source2_page_type
    ,NULL AS source2_page_section
    ,NULL AS source2_target_type
    ,NULL AS source1_feature_detail
    ,NULL AS source2_feature_detail
    ,concat_ws(
        '-',
        array(
            page_type,
            page_section[0],
            target_type
        )
    ) AS feature_detail
    ,app_version
    ,rn_version
    ,cast(
        coalesce(
            parse_data.is_ads,
            parse_search_info.is_ads,
            parse_data.params.is_ads
        ) AS BOOLEAN
    ) AS is_ads
    ,cast(
        coalesce(
            parse_data.location,
            parse_data.search_FE.item.location,
            parse_data.search_FE.location,
            parse_data.search_FE.absolute_location,
            parse_data.params.index,
            parse_data.search_FE.module.location
        ) AS INT
    ) AS location
    ,cast(
        coalesce(
            parse_data.itemid,
            parse_data.item.itemid,
            parse_data.item_id,
            parse_data.params.item_id
        ) AS BIGINT
    ) AS item_id
    ,cast(parse_data.collection_id AS STRING) AS knode_id
    ,cast(coalesce(
        parse_data.search_FE.search_params.keyword,
        parse_data.search_params.keyword,
        parse_data.keyword,
        parse_data.search_FE.keyword,
        parse_data.search_FE.hint_text,
        parse_data.hint_text
    ) AS STRING) AS keyword
    ,cast(coalesce(
        parse_data.shopid,
        parse_data.item.shopid,
        parse_data.shop_id,
        parse_data.ctx_shopid,
        parse_data.search_FE.shopid,
        parse_data.params.shop_id
    ) AS BIGINT) AS shop_id
    ,deviceid AS device_id
    ,userid AS user_id
    ,array_distinct(
        flatten(
            array(
                coalesce(parse_search_info.ab_sign, array()),
                coalesce(transform(
                    split(regexp_extract(parse_data.recommendation_info,'AB:([^,]*)', 1), "\\|"),
                    x -> CAST(if(split(x, '_')[2] IS NOT NULL, split(x, '_')[2], x) AS INT)
                    ), array()
                ),
                coalesce(transform(
                    split(regexp_extract(parse_data.params.recommendation_algorithm,'AB:([^,]*)', 1), "\\|"),
                    x -> CAST(if(split(x, '_')[2] IS NOT NULL, split(x, '_')[2], x) AS INT)
                    ), array()
                ),
                coalesce(parse_data.be_ab, array()),
                coalesce(exp_group_id, array()),
                coalesce(transform(
                    split(regexp_extract(url_decode(regexp_extract(parse_data.params.recommendation_algorithm, 'MIXERINFO:([^,]+)', 1))
                    ,'AB:([^,]*)', 1), "\\|"),
                    x -> CAST(if(split(x, '_')[2] IS NOT NULL, split(x, '_')[2], x) AS INT)
                    ), array())
            )
        )
    ) AS exp_group_ids
    ,1 AS operation_cnt
    ,cast(parse_data.card_type AS STRING) AS card_type
    ,event_timestamp
    ,log_timestamp
    ,event_id
    ,cast(parse_data.is_group_buy AS BOOLEAN) AS is_group_buy
    ,CASE
        WHEN
            cast(
               parse_data.ctx_itemid AS BIGINT
            ) IS NOT NULL
            AND cast(
                parse_data.ctx_shopid AS BIGINT
            ) IS NOT NULL
            THEN array(
                named_struct(
                    'shopid',
                    cast(
                        parse_data.ctx_shopid AS BIGINT
                    ),
                    'itemid',
                    cast(
                        parse_data.ctx_itemid AS BIGINT
                    )
                ))
        ELSE NULL
    END AS ctx_items
    ,cast(parse_data.model_id AS BIGINT) AS model_id
    ,NULL AS place_order_gmv
    ,NULL AS place_order_gmv_local
    ,is_back
    ,coalesce(
        NULLIF(parse_search_info.request_id, '')
        ,NULLIF(regexp_extract(parse_data.recommendation_info,'REQID:([^,]*)', 1), '')
        ,NULLIF(regexp_extract(parse_data.params.recommendation_algorithm,'REQID:([^,]*)', 1), '')
        ,NULLIF(GET_JSON_OBJECT(GET_JSON_OBJECT(data, '$.params.search_info'), '$.request_id'), '')
        ,NULLIF(GET_JSON_OBJECT(GET_JSON_OBJECT(data, '$.params.search_info'), '$.reqid'), '')
    ) AS request_id
    ,parse_data.search_FE.search_params.search_scenario.key AS search_scenario_key
    ,get_json_object(data, '$.search_FE.search_entrance.entrance') AS search_entrance
    ,get_json_object(data, '$.search_FE.search_entrance.mid') AS search_mid
    ,parse_data.search_FE.md5 AS md5
    ,cast(parse_search_info.item_similarity AS DOUBLE) AS item_similarity
    ,CASE
        WHEN parse_data.search_FE.image_source = '' THEN NULL
        ELSE parse_data.search_FE.image_source
    END AS image_source
    ,cast(parse_data.liked AS BOOLEAN) AS liked
    ,parse_data.search_FE.search_params.sortBy AS sort_type
    ,CASE
        WHEN target_type = 'item' THEN target_property
        ELSE null
    END AS target_property
    ,domain
    ,session_id
    ,parse_data.search_FE.search_params.search_session_id as search_session_id
    ,parse_data.search_FE.search_params.global_session_id as global_session_id
    ,parse_data.search_FE.input_type AS input_type
    ,platform_implementation
    ,parse_data.search_FE.version as camera_page_version
    ,parse_data.upstream AS upstream_feature
    ,pre_source
    ,last_view_event_id
    ,last_view_civ_id
    ,civ_id
    ,operation as original_operation
    ,parse_search_info.groupid as groupid
    ,parse_search_info.user_type as user_type
    ,parse_data.search_FE.search_params.last_keyword as last_keyword
    ,parse_data.search_params.searchPrefill AS search_prefill_id
    ,COALESCE(parse_data.search_FE.search_params.order, parse_data.search_params.order) AS sort_order
    ,parse_data.user_input AS user_input
    ,COALESCE(parse_data.search_FE.query_rewrite.rewrite_keyword, parse_search_info.query_rewrite.rewrite_keyword) AS rewrite_keyword
    ,COALESCE(parse_data.search_FE.query_rewrite.ori_keyword, parse_search_info.query_rewrite.ori_keyword) AS origin_rewrite_keyword
    ,COALESCE(parse_data.search_FE.query_rewrite.fe_query_rewrite_status, parse_search_info.query_rewrite.fe_query_rewrite_status) AS fe_querywrite_status
    ,COALESCE(parse_data.search_FE.query_rewrite.rewrite_type, parse_search_info.query_rewrite.rewrite_type) AS rewrite_id
    ,parse_data.search_params.reserved_keyword AS reserved_keyword
    ,parse_data.ads_id
    ,pre_source
    ,COALESCE(parse_data.params.content_mix_frame_tab_name, parse_data.content_mix_frame_tab_name) AS content_mix_frame_tab_name
    ,parse_data.position.current_page AS position_current_page
    ,cast(parse_data.ctx_item_type as int) as ctx_item_type
    ,parse_data.vsku_info as vsku_info
    ,parse_data.search_FE.dre_version AS dre_version
    ,GET_JSON_OBJECT(data, '$.search_FE.search_entrance.context.voice_search_session_id') AS voice_search_session_id
    ,parse_data.meta.business_id AS business_id
    ,parse_data.params.content_type AS content_type
    ,COALESCE(
        NULLIF(parse_data.params.sv_source_request_id, '')
       ,NULLIF(regexp_extract(parse_data.params.sv_source_recommendation_algorithm,'REQID:([^,]*)', 1), '')
       ,NULLIF(GET_JSON_OBJECT(parse_data.params.sv_source_search_info, '$.request_id'), '')
     ) AS sv_source_request_id
    ,cast(parse_data.params.sv_source_location as int) AS sv_source_location
    ,CASE
         WHEN page_type = 'streaming_room' THEN parse_data.streaming_id
         ELSE NULL
     END AS content_id
    ,cast(parse_data.content_location as int) as content_location
    ,parse_data.from_source as from_source
    ,parse_data.live_scene_parameters.live_in_search.request_id as live_in_search_request_id
    ,cast(parse_data.live_scene_parameters.live_in_search.itemid as bigint) as live_in_search_item_id
    ,cast(parse_data.live_scene_parameters.live_in_search.location as int) as live_in_search_location
    ,GET_JSON_OBJECT(parse_data.search_FE.header, '$.ai_summary') AS fe_header_ai_summary
    ,parse_data.search_FE.topic_navigation AS fe_topic_navigation
    ,CAST(GET_JSON_OBJECT(parse_data.srp_ai_topic_info, '$.srp_location') AS INT) AS ai_topic_srp_location
    ,GET_JSON_OBJECT(parse_data.srp_ai_topic_info, '$.srp_title') AS ai_topic_srp_title
    ,parse_data.ai_search_info AS ai_search_info
    ,parse_data.search_FE.search_params.search_scenario.be_key AS search_scenario_be_key

    ,local_date
    ,local_hour
    ,regional_date
    ,regional_hour
    ,grass_region
    ,operation
FROM
    traffic_view_pre_parse_${grass_region_without_quote}

