CREATE TEMPORARY VIEW omni_ppv_add_all_tags_${grass_region_without_quote} AS
SELECT
    *
    ,get_all_tag('click',page_type,page_section[0],target_type,get_feature_prefix(page_type,search_mid,search_entrance),'null',event_id) as all_tags
    ,get_all_tag('click',source1_mapped_page_type,source1_page_section[0],source1_target_type,get_feature_prefix(source1_mapped_page_type,source1_search_mid,source1_search_entrance),'null',event_id) as source1_all_tags
    ,get_all_tag('click',source2_mapped_page_type,source2_page_section[0],source2_target_type,get_feature_prefix(source2_mapped_page_type,source2_search_mid,source2_search_entrance),'null',event_id) as source2_all_tags
FROM omni_ppv_parse_${grass_region_without_quote}
WHERE grass_date = ${local_date}
    AND grass_region IN (${grass_region})
    AND local_date = ${local_date}
;
