CREATE TEMPORARY VIEW click_search_domain_map_${grass_region_without_quote} AS
SELECT
    mapped_page_type
    ,scenario_key
    ,tz_type
    ,grass_region
FROM
    mp_foa.dim_search_domain_map__reg_live
WHERE
    grass_region IN (${grass_region})
    AND grass_date = date_sub(${local_date}, 1);

--sql_divide_splitter--

CACHE TABLE click_search_mid_mapping_${grass_region_without_quote} AS
SELECT
    page_type AS mid_map_page_type
    ,CASE
        WHEN page_section = '-' THEN NULL
        ELSE page_section
    END AS mid_map_page_section
    ,CASE
        WHEN target_type = '-' THEN NULL
        ELSE target_type
    END AS mid_map_target_type
    ,CASE
        WHEN value = '' THEN NULL
        ELSE value
    END AS value
    ,mid
FROM
    srdi_mart.dim_sr_data_warehouse_search_mid_mapping;     -- from g-sheet:https://docs.google.com/spreadsheets/d/1lOVQuX6EZGxEezpSUuhb2-F_WgsSo3Ms4FRJw1aN8qc/edit#gid=1619339711

--sql_divide_splitter--

CREATE TEMPORARY VIEW traffic_click_join_${grass_region_without_quote} AS
SELECT /*+ BROADCAST(search_domain_map) */
    platform
    ,CASE
        WHEN search_scenario_key IS NULL THEN page_type
        WHEN search_domain_map.mapped_page_type IS NULL THEN page_type
        ELSE mapped_page_type
    END AS page_type
    ,page_section
    ,target_type
    ,source1_page_type
    ,source1_page_section
    ,source1_target_type
    ,source2_page_type
    ,source2_page_section
    ,source2_target_type
    ,source1_feature_detail
    ,source2_feature_detail
    ,concat_ws(
        '-',
        array(
            CASE
                WHEN search_scenario_key IS NULL THEN page_type
                WHEN search_domain_map.mapped_page_type IS NULL THEN page_type
                ELSE mapped_page_type
            END,
            page_section[0],
            target_type
        )
    ) AS feature_detail
