CREATE TEMPORARY VIEW view_search_domain_map_${grass_region_without_quote} AS
SELECT
    mapped_page_type
    ,scenario_key
    ,tz_type
    ,grass_region
FROM
    mp_foa.dim_search_domain_map__reg_live
WHERE
    grass_region IN (${grass_region})
    AND grass_date = date_sub(${local_date}, 1);

--sql_divide_splitter--

CREATE TEMPORARY VIEW traffic_view_join_${grass_region_without_quote} AS
SELECT /*+ BROADCAST(search_domain_map) */
    platform
    ,CASE
        WHEN search_scenario_key IS NULL THEN page_type
        WHEN search_domain_map.mapped_page_type IS NULL THEN page_type
        ELSE mapped_page_type
    END AS page_type
    ,page_section
    ,target_type
    ,source1_page_type
    ,source1_page_section
    ,source1_target_type
    ,source2_page_type
    ,source2_page_section
    ,source2_target_type
    ,source1_feature_detail
    ,source2_feature_detail
    ,concat_ws(
        '-',
        array(
            CASE
                WHEN search_scenario_key IS NULL THEN page_type
                WHEN search_domain_map.mapped_page_type IS NULL THEN page_type
                ELSE mapped_page_type
            END,
            page_section[0],
            target_type
        )
    ) AS feature_detail
    ,app_version
    ,rn_version
    ,is_ads
    ,location
    ,item_id
    ,knode_id
    ,keyword
    ,shop_id
    ,device_id
    ,user_id
    ,exp_group_ids
    ,operation_cnt
    ,card_type
    ,event_timestamp
    ,log_timestamp
    ,event_id
    ,is_group_buy
    ,ctx_items
    ,model_id
    ,place_order_gmv
    ,place_order_gmv_local
    ,is_back
    ,request_id
    ,platform_implementation
    ,upstream_feature
    ,local_date
    ,local_hour
    ,regional_date
    ,regional_hour
    ,view.grass_region
    ,operation
    ,view.session_id
    ,pre_source
    ,last_view_event_id
    ,last_view_civ_id
    ,civ_id
    ,page_type AS original_page_type
    ,view.original_operation
    ,view.ads_id

    ,search_entrance
    ,search_mid
    ,md5
    ,item_similarity
    ,image_source
    ,liked
    ,sort_type
    ,target_property
    ,search_session_id
    ,input_type
    ,camera_page_version
    ,global_session_id
    ,groupid
    ,user_type
    ,last_keyword
    ,search_prefill_id
    ,sort_order
    ,user_input
    ,rewrite_keyword
    ,origin_rewrite_keyword
    ,fe_querywrite_status
    ,rewrite_id
    ,reserved_keyword
    ,pre_source.page_type AS pre_source_page_type
    ,pre_source.page_section AS pre_source_page_section
    ,pre_source.target_type AS pre_source_target_type
    ,content_mix_frame_tab_name
    ,position_current_page
    ,ctx_item_type
    ,vsku_info
    ,dre_version
    ,voice_search_session_id
    ,pre_source.event_id AS pre_source_event_id
    ,business_id
    ,content_type
    ,sv_source_request_id
    ,sv_source_location
    ,content_id
    ,content_location
    ,live_in_search_request_id
    ,live_in_search_item_id
    ,live_in_search_location
    ,from_source
    ,fe_header_ai_summary
    ,fe_topic_navigation
    ,ai_topic_srp_location
    ,ai_topic_srp_title
    ,ai_search_info
    ,search_scenario_be_key
FROM traffic_view_parse_${grass_region_without_quote} AS view
LEFT JOIN view_search_domain_map_${grass_region_without_quote} AS search_domain_map
    ON view.search_scenario_key = search_domain_map.scenario_key
    AND view.grass_region = search_domain_map.grass_region
WHERE
    local_date = ${local_date}
    AND local_hour = ${local_hour}
    AND view.grass_region IN (${grass_region});

